    51→#[must_use]
    52→pub fn compute_epoch_at_slot<P: Preset>(slot: Slot) -> Epoch {
    53→    slot.div_typenum::<P::SlotsPerEpoch>()
    54→}
    55→
    56→#[must_use]
    57→pub const fn compute_start_slot_at_epoch<P: Preset>(epoch: Epoch) -> Slot {
    58→    epoch.saturating_mul(P::SlotsPerEpoch::U64)
    59→}
    60→
    61→#[must_use]
    62→pub fn is_epoch_start<P: Preset>(slot: Slot) -> bool {
    63→    slots_since_epoch_start::<P>(slot) == 0
