    66→#[expect(
    67→    clippy::unnecessary_min_or_max,
    68→    reason = "GENESIS_EPOCH const might be adjusted independently."
    69→)]
    70→#[must_use]
    71→pub fn previous_epoch(epoch: Epoch) -> Epoch {
    72→    epoch.saturating_sub(1).max(GENESIS_EPOCH)
    73→}
    74→
    75→#[expect(
    76→    clippy::unnecessary_min_or_max,
    77→    reason = "GENESIS_SLOT const might be adjusted independently."
