   114→// > Return the 32-byte fork data root for the ``current_version`` and ``genesis_validators_root``.
   115→// > This is used primarily in signature domains to avoid collisions across forks/chains.
   116→fn compute_fork_data_root(current_version: Version, genesis_validators_root: H256) -> H256 {
   117→    ForkData {
   118→        current_version,
   119→        genesis_validators_root,
   120→    }
   121→    .hash_tree_root()
   122→}
   123→
   124→// > Return the 4-byte fork digest for the ``current_version`` and ``genesis_validators_root``.
   125→// > This is a digest primarily used for domain separation on the p2p layer.
   126→// > 4-bytes suffices for practical separation of forks/chains.
   127→fn compute_fork_digest_pre_fulu(
   128→    current_version: Version,
   129→    genesis_validators_root: H256,
   130→) -> ForkDigest {
   131→    let root = compute_fork_data_root(current_version, genesis_validators_root);
   132→    ForkDigest::from_slice(&root[..ForkDigest::len_bytes()])
   133→}
   134→
   135→// > Return the 4-byte fork digest for the ``version`` and ``genesis_validators_root``
   136→// > XOR'd with the hash of the blob parameters for ``epoch``.
   137→//
   138→// > This is a digest primarily used for domain separation on the p2p layer.
   139→// > 4-bytes suffices for practical separation of forks/chains.
   140→fn compute_fork_digest_post_fulu(
   141→    config: &Config,
   142→    genesis_validators_root: H256,
   143→    epoch: Epoch,
   144→) -> ForkDigest {
   145→    let fork_version = config.version_at_epoch(epoch);
   146→    let blob_entry = config.get_blob_schedule_entry(epoch);
   147→    let mut bytes = [0u8; 16];
   148→    bytes[..8].copy_from_slice(&blob_entry.epoch.to_le_bytes());
   149→    bytes[8..].copy_from_slice(
   150→        &u64::try_from(blob_entry.max_blobs_per_block)
   151→            .expect("number of max blobs should fit in u64")
   152→            .to_le_bytes(),
   153→    );
   154→    let hash = H256::from_slice(&Sha256::digest(bytes));
   155→    let root = compute_fork_data_root(fork_version, genesis_validators_root);
   156→    let bitmask_digest = root ^ hash;
   157→    ForkDigest::from_slice(&bitmask_digest[..ForkDigest::len_bytes()])
   158→}
   159→
   160→#[must_use]
   161→pub fn compute_fork_digest(
   162→    config: &Config,
   163→    genesis_validators_root: H256,
   164→    epoch: Epoch,
   165→) -> ForkDigest {
   166→    if config.phase_at_epoch(epoch).is_peerdas_activated() {
   167→        compute_fork_digest_post_fulu(config, genesis_validators_root, epoch)
   168→    } else {
   169→        let fork_version = config.version_at_epoch(epoch);
   170→        compute_fork_digest_pre_fulu(fork_version, genesis_validators_root)
   171→    }
   172→}
