   174→#[must_use]
   175→pub fn compute_domain(
   176→    config: &Config,
   177→    domain_type: DomainType,
   178→    fork_version: Option<Version>,
   179→    genesis_validators_root: Option<H256>,
   180→) -> Domain {
   181→    let fork_version = fork_version.unwrap_or(config.genesis_fork_version);
   182→    let genesis_validators_root = genesis_validators_root.unwrap_or_else(H256::zero);
   183→    let fork_data_root = compute_fork_data_root(fork_version, genesis_validators_root);
   184→
   185→    let mut domain = Domain::zero();
   186→    domain[..DomainType::len_bytes()].copy_from_slice(domain_type.as_bytes());
   187→    domain[DomainType::len_bytes()..].copy_from_slice(&fork_data_root[..28]);
   188→    domain
   189→}
