   313→/// [`compute_subnet_for_attestation`](https://github.com/ethereum/consensus-specs/blob/v1.3.0/specs/phase0/validator.md#broadcast-attestation)
   314→pub fn compute_subnet_for_attestation<P: Preset>(
   315→    committees_per_slot: u64,
   316→    slot: Slot,
   317→    committee_index: CommitteeIndex,
   318→) -> Result<SubnetId> {
   319→    ensure!(
   320→        committee_index < committees_per_slot,
   321→        Error::CommitteeIndexOutOfBounds,
   322→    );
   323→
   324→    let slots_since_epoch_start = slots_since_epoch_start::<P>(slot);
   325→    let committees_since_epoch_start = committees_per_slot * slots_since_epoch_start;
   326→
   327→    Ok((committees_since_epoch_start + committee_index).mod_typenum::<AttestationSubnetCount>())
   328→}
