   330→/// [`compute_subnet_for_blob_sidecar`](https://github.com/ethereum/consensus-specs/blob/v1.4.0-beta.1/specs/deneb/validator.md#sidecar)
   331→pub fn compute_subnet_for_blob_sidecar<P: Preset>(
   332→    config: &Config,
   333→    blob_sidecar: &BlobSidecar<P>,
   334→) -> SubnetId {
   335→    let phase = config.phase_at_slot::<P>(blob_sidecar.signed_block_header.message.slot);
   336→
   337→    blob_sidecar.index % config.blob_sidecar_subnet_count(phase)
   338→}
