   340→// source: https://github.com/ethereum/consensus-specs/pull/3574/files/cebf78a83e6fc8fa237daf4264b9ca0fe61473f4#diff-96cf4db15bede3d60f04584fb25339507c35755959159cdbe19d760ca92de109R106
   341→#[must_use]
   342→pub const fn compute_subnet_for_data_column_sidecar(
   343→    config: &Config,
   344→    column_index: ColumnIndex,
   345→) -> SubnetId {
   346→    column_index % config.data_column_sidecar_subnet_count
   347→}
