   457→#[must_use]
   458→pub fn committee_count_from_active_validator_count<P: Preset>(active_validator_count: u64) -> u64 {
   459→    active_validator_count
   460→        .div_typenum::<P::SlotsPerEpoch>()
   461→        .div(P::TARGET_COMMITTEE_SIZE)
   462→        .clamp(1, P::MaxCommitteesPerSlot::U64)
   463→}
   464→
   465→// <https://github.com/ethereum/consensus-specs/blob/dc17b1e2b6a4ec3a2104c277a33abae75a43b0fa/specs/phase0/validator.md#bls_withdrawal_prefix>
   466→#[must_use]
   467→pub fn bls_withdrawal_credentials(public_key: PublicKeyBytes) -> H256 {
   468→    let mut withdrawal_credentials = hashing::hash_384(public_key);
   469→    withdrawal_credentials[..BLS_WITHDRAWAL_PREFIX.len()].copy_from_slice(BLS_WITHDRAWAL_PREFIX);
   470→    withdrawal_credentials
   471→}
   472→
   473→// <https://github.com/ethereum/consensus-specs/blob/dc17b1e2b6a4ec3a2104c277a33abae75a43b0fa/specs/phase0/validator.md#eth1_address_withdrawal_prefix>
   474→#[must_use]
   475→pub fn eth1_address_withdrawal_credentials(address: ExecutionAddress) -> H256 {
   476→    let mut withdrawal_credentials = H256::zero();
   477→
   478→    withdrawal_credentials[..ETH1_ADDRESS_WITHDRAWAL_PREFIX.len()]
