   510→pub fn deneb_kzg_commitment_inclusion_proof<P: Preset>(
   511→    body: &(impl PostDenebBeaconBlockBody<P> + ?Sized),
   512→    commitment_index: BlobIndex,
   513→) -> Result<BlobCommitmentInclusionProof<P>> {
   514→    let depth = P::KzgCommitmentInclusionProofDepth::USIZE;
   515→
   516→    let mut proof = ContiguousVector::default();
   517→    let mut merkle_tree = MerkleTree::<BlobCommitmentTreeDepth<P>>::default();
   518→
   519→    let chunks = body
   520→        .blob_kzg_commitments()
   521→        .iter()
   522→        .map(SszHash::hash_tree_root);
   523→
   524→    let commitment_indices = 0..body.blob_kzg_commitments().len();
   525→    let proof_indices = commitment_index.try_into()?..(commitment_index + 1).try_into()?;
   526→
   527→    let subproof = merkle_tree
   528→        .extend_and_construct_proofs(chunks, commitment_indices, proof_indices)
   529→        .exactly_one()
   530→        .ok()
   531→        .expect("exactly one proof is requested");
   532→
   533→    // The first 13 or 5 nodes are computed from other elements of `body.blob_kzg_commitments`.
   534→    proof[..depth - 4].copy_from_slice(subproof.as_slice());
   535→
   536→    // The last 4 nodes are computed from other fields of `body`.
   537→    proof[depth - 4] = body.bls_to_execution_changes().hash_tree_root();
   538→
   539→    proof[depth - 3] = hashing::hash_256_256(
   540→        body.sync_aggregate().hash_tree_root(),
   541→        body.execution_payload().hash_tree_root(),
   542→    );
   543→
   544→    proof[depth - 2] = ZERO_HASHES[2];
   545→
   546→    proof[depth - 1] = hashing::hash_256_256(
   547→        hashing::hash_256_256(
   548→            hashing::hash_256_256(
   549→                body.randao_reveal().hash_tree_root(),
   550→                body.eth1_data().hash_tree_root(),
   551→            ),
   552→            hashing::hash_256_256(body.graffiti(), body.proposer_slashings().hash_tree_root()),
   553→        ),
   554→        hashing::hash_256_256(
   555→            hashing::hash_256_256(body.attester_slashings_root(), body.attestations_root()),
   556→            hashing::hash_256_256(
   557→                body.deposits().hash_tree_root(),
   558→                body.voluntary_exits().hash_tree_root(),
   559→            ),
   560→        ),
   561→    );
   562→
   563→    Ok(proof)
   564→}
