    28→            .any(move |(blob_identifier, (blob_sidecar, blob_slot, _))| {
    29→                let blob_proposer_index = blob_sidecar.signed_block_header.message.proposer_index;
    30→
    31→                *blob_slot == slot
    32→                    && blob_proposer_index == proposer_index
    33→                    && blob_identifier.block_root != block_root
    34→            })
    35→    }
