    38→        Some(self.blobs.get(&blob_id)?.0.clone_arc())
    39→    }
    40→
    41→    pub fn has_unpersisted_blob_sidecars(&self) -> bool {
    42→        self.blobs.iter().any(|(_, (_, _, persisted))| !persisted)
    43→    }
